    def __init__(self, sm_params, name=None, io_connection=None, io_type=None, variant=None, io_constructor_kwargs=None,
                 initial_state=None, lazy_cmds_events=False, cus_airscale_side="left"):
        """
        Create unix device communicating over io_connection.

        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: External-IO connection connection type
        :param variant: External-IO connection variant
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: Initial state for device
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        :param cus_airscale_side: side of AirScale. Left or right option.
        """
        sm_params = sm_params.copy()
        initial_state = initial_state if initial_state is not None else CusController.fct

        # default value for side is left
        if cus_airscale_side == "right":
            self._cus_airscale_side = "right"
            self.fsps_states = self.fsps_states_right
            self.node_ids = self.node_ids_right
        else:
            self._cus_airscale_side = "left"
            self.fsps_states = self.fsps_states_left
            self.node_ids = self.node_ids_left

        super(CusController, self).__init__(sm_params=sm_params, name=name, io_connection=io_connection,
                                            io_type=io_type, variant=variant,
                                            io_constructor_kwargs=io_constructor_kwargs, initial_state=initial_state,
                                            lazy_cmds_events=lazy_cmds_events)
        self.logger = logging.getLogger('moler.cus_controller')

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_with_proxy_pc(self):
        """
        Return State Machine default configuration with proxy_pc state.

        :return: default sm configuration with proxy_pc state.
        """
        config = {
            CusController.connection_hops: {
                CusController.proxy_pc: {  # from
                    CusController.fct: self.__get_command_to_connect_fct(),
                },
                CusController.fct: {  # from
                    CusController.proxy_pc: self.__get_command_to_exit_fct(is_proxy_pc=True),
                },
            }
        }
        self.__update_change_per_fsp(config)
        self.__update_dsp_change_configuration(config)
        return config

    @mark_to_call_base_class_method_with_same_name
    def _prepare_transitions_with_proxy_pc(self):
        """
        Prepare transitions to change states with proxy_pc state.

        :return: transitions with proxy_pc state.
        """
        transitions = {
            # modification for FSPs
            CusController.fct: {
                CusController.proxy_pc: ACTION_TO_CHANGE_STATE,
            },
            CusController.proxy_pc: {
                CusController.fct: ACTION_TO_CHANGE_STATE,
                CusController.unix_local: ACTION_TO_CHANGE_STATE
            },
            CusController.unix_local: {
                CusController.proxy_pc: ACTION_TO_CHANGE_STATE
            },
            # modification for all DSPs
        }
        self.__update_transitions_for_cus_states(transitions)
        return transitions

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_with_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine with proxy_pc state.

        :return: textual prompt for each state with proxy_pc state.
        """
        state_prompts = {
            CusController.fct:
                self.__generate_fct_prompt(),
            CusController.proxy_pc:
                self.__get_expected_prompt_for_proxy_pc(),
        }
        self.__update_state_prompts(state_prompts)
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_without_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine without proxy_pc state.

        :return: textual prompt for each state without proxy_pc state.
        """
        state_prompts = {
            CusController.fct:
                self.__generate_fct_prompt(),
        }
        self.__update_state_prompts(state_prompts)
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        state_hops = {}
        self.__add_next_hop_for_not_connected(state_hops, is_proxy_connection=True)
        self.__add_next_hop_for_unix_local(state_hops, is_proxy_connection=True)
        self.__add_next_hop_for_unix_local_root(state_hops, is_proxy_connection=True)
        self.__add_next_hop_for_proxy_pc(state_hops)
        self.__add_next_hop_for_fct(state_hops, is_proxy_connection=True)
        self.__add_next_hop_for_fsp(state_hops, is_proxy_connection=True)
        self.__add_next_hop_for_dsp_list(state_hops, is_proxy_connection=True)

        return state_hops

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(CusController, self)._get_packages_for_state(state, observer)

        if not available:
            if state == CusController.fct:
                available = self.__get_fct_packages()
            elif re.search(r"dsp", state):
                available = self.__get_dsp_packages()
            elif re.search(r"fsp", state):
                available = self.__get_fsp_packages()
            if available:
                return available[observer]

        return available

    def __update_state_prompts(self, state_prompts):
        for fsp in self.fsps_states.keys():
            state_prompts[fsp] = CusController.__generate_fsp_prompt(fsp)
            for dsp in self.fsps_states[fsp]:
                dsp_number = CusController.__get_dsp_number_from_state(dsp)
                state_prompts[dsp] = self.__generate_dsp_prompt(dsp_number=dsp_number, fsp_state=fsp)

    def __add_next_hop_for_dsp_list(self, state_hops, is_proxy_connection):
        for fsp in self.fsps_states.keys():
            for dsp in self.fsps_states[fsp]:
                next_hop_left = fsp
                dsp_elements = {
                    CusController.unix_local: next_hop_left,
                    CusController.unix_local_root: next_hop_left,
                    CusController.not_connected: next_hop_left,
                    CusController.fct: next_hop_left
                }
                if is_proxy_connection:
                    dsp_elements[CusController.proxy_pc] = next_hop_left

                other_dsps = self.__get_states_except_one(self.fsps_states[fsp], dsp)
                for other_dsp in other_dsps:
                    dsp_elements[other_dsp] = next_hop_left
                other_fsps = self.__get_states_except_one(self.fsps_states.keys(), fsp)
                for other_fsp in other_fsps:
                    dsp_elements[other_fsp] = next_hop_left
                    for other_fsp_dsp in self.fsps_states[other_fsp]:
                        dsp_elements[other_fsp_dsp] = next_hop_left
                state_hops.update({dsp: dsp_elements})

    @staticmethod
    def __get_states_except_one(states, except_state):
        other_states = filter(lambda x: x != except_state, states)
        return other_states

    def __add_next_hop_for_not_connected(self, state_hops, is_proxy_connection=True):
        next_hop = CusController.unix_local
        nc_elements = {
            CusController.fct: next_hop
        }
        if is_proxy_connection:
            nc_elements[CusController.proxy_pc] = next_hop

        nc_elements.update(self.__get_hops_for_fsps_and_dsps(next_hop))
        state_hops.update({CusController.not_connected: nc_elements})

    def __add_next_hop_for_unix_local(self, state_hops, is_proxy_connection=True):
        if is_proxy_connection:
            next_hop = CusController.proxy_pc
        else:
            next_hop = CusController.fct

        nc_elements = {
            CusController.fct: next_hop
        }
        nc_elements.update(self.__get_hops_for_fsps_and_dsps(next_hop))
        state_hops.update({CusController.unix_local: nc_elements})

    def __add_next_hop_for_unix_local_root(self, state_hops, is_proxy_connection=True):
        next_hop = CusController.unix_local
        nc_elements = {
            CusController.fct: next_hop,
            CusController.not_connected: next_hop
        }
        if is_proxy_connection:
            nc_elements[CusController.proxy_pc] = next_hop
        nc_elements.update(self.__get_hops_for_fsps_and_dsps(next_hop))
        state_hops.update({CusController.unix_local_root: nc_elements})

    def __add_next_hop_for_proxy_pc(self, state_hops):
        next_hop_right = CusController.fct
        next_hop_left = CusController.unix_local
        nc_elements = {
            CusController.not_connected: next_hop_left,
            CusController.unix_local_root: next_hop_left
        }

        nc_elements.update(self.__get_hops_for_fsps_and_dsps(next_hop_right))
        state_hops.update({CusController.proxy_pc: nc_elements})

    def __get_hops_for_fsps_and_dsps(self, next_hop):
        nc_elements = {}
        for fsp in self.fsps_states.keys():
            nc_elements[fsp] = next_hop
            for dsp in self.fsps_states[fsp]:
                nc_elements[dsp] = next_hop
        return nc_elements

    def __add_next_hop_for_fct(self, state_hops, is_proxy_connection=True):
        if is_proxy_connection:
            next_hop_left = CusController.proxy_pc
        else:
            next_hop_left = CusController.unix_local
        fct_element = {
            CusController.not_connected: next_hop_left,
            CusController.unix_local_root: next_hop_left
        }
        if is_proxy_connection:
            fct_element[CusController.unix_local] = next_hop_left

        for fsp in self.fsps_states.keys():
            for dsp in self.fsps_states[fsp]:
                fct_element[dsp] = fsp
        state_hops.update({CusController.fct: fct_element})

    def __add_next_hop_for_fsp(self, state_hops, is_proxy_connection=True):
        next_hop_left = CusController.fct
        fsp_element = {
            CusController.not_connected: next_hop_left,
            CusController.unix_local: next_hop_left,
            CusController.unix_local_root: next_hop_left
        }
        if is_proxy_connection:
            fsp_element[CusController.proxy_pc] = next_hop_left

        for fsp in self.fsps_states.keys():
            current_element = dict(fsp_element)
            other_fsps = self.__get_states_except_one(self.fsps_states.keys(), fsp)
            for other_fsp in other_fsps:
                current_element[other_fsp] = next_hop_left
                for dsp in self.fsps_states[other_fsp]:
                    current_element[dsp] = next_hop_left
            state_hops.update({fsp: current_element})

    def __update_transitions_for_cus_states(self, transitions):
        for fsp in self.fsps_states.keys():
            transitions[CusController.fct].update({fsp: ACTION_TO_CHANGE_STATE})
            transitions[fsp] = {CusController.fct: ACTION_TO_CHANGE_STATE}
            for dsp in self.fsps_states[fsp]:
                transitions[fsp].update({dsp: ACTION_TO_CHANGE_STATE})
                transitions[dsp] = {fsp: ACTION_TO_CHANGE_STATE}

    @staticmethod
    def __get_dsp_packages():
        return {CusController.cmds: ['ta_moler.cmd.rtg_ctrl.dsp'],
                CusController.events: ['moler.events.shared']}

    @staticmethod
    def __get_fsp_packages():
        return {CusController.cmds: ['moler.cmd.unix', 'ta_moler.cmd.rtg_ctrl.linux', 'ta_moler.cmd.cus_ctrl.fsp'],
                CusController.events: ['moler.events.shared', 'moler.events.unix']}

    @staticmethod
    def __get_fct_packages():
        return {CusController.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix',
                                     'ta_moler.cmd.shared.enblinux',
                                     'ta_moler.cmd.fzmconsole.linux', 'ta_moler.cmd.rtg_ctrl.linux',
                                     'ta_moler.cmd.cus_ctrl.fct'],
                CusController.events: ['moler.events.shared', 'moler.events.unix',
                                       'ta_moler.events.fzmconsole', 'ta_moler.events.rtg_ctrl']}

    @staticmethod
    def __get_command_to_exit_fct(is_proxy_pc):
        command = {  # to
            "execute_command": "exit",  # using command
            "command_params": {  # with parameters
            },
        }
        if is_proxy_pc:
            command["required_command_params"] = ["expected_prompt"]
        return command

    @staticmethod
    def __get_command_to_connect_fct():
        return {  # to
            "execute_command": "ssh",  # using command
            "command_params": {  # with parameters
                "expected_prompt": CusController.__generate_fct_prompt(),
                "login": "toor4nsn",
                "password": "oZPS0POrRieRtu",
                "allowed_newline_after_prompt": True,
            },
            "required_command_params": [
                "host",
            ]
        }

    def __generate_change_from_dsp_sm_configuration(self, dsp_number, fsp):
        return {
            fsp: {
                "execute_command": "exit_mmi",  # using command
                "command_params":
                    {  # with parameters
                        "prompt": self.__generate_dsp_prompt(dsp_number, fsp),
                        "expected_prompt": CusController.__generate_fsp_prompt(fsp),
                    },
                "required_command_params": []
            }
        }

    def __generate_change_to_dsp_sm_configuration(self, dsp_number, fsp_state):
        return {  # to
            "execute_command": "mmi",
            "command_params": {
                "expected_prompt": self.__generate_dsp_prompt(dsp_number, fsp_state),
                "dsp_number": dsp_number,
            },
            "required_command_params": []
        }

    @staticmethod
    def __generate_change_to_fct_from_fsp_sm_configuration():
        return {  # to
            "execute_command": "exit",
            "command_params": {
                "expected_prompt": CusController.__generate_fct_prompt()
            },
            "required_command_params": []
        }

    @staticmethod
    def __generate_change_to_fsp_from_fct_sm_configuration(fsp_state):
        # nowa komenda
        return {  # to
            "execute_command": "fsp",
            "command_params": {
                "expected_prompt": CusController.__generate_fsp_prompt(fsp_state),
                "fsp_number": re.findall(r'fsp-(\d\w)', fsp_state)[0],
                "timeout": 40
            },
            "required_command_params": []
        }

    def __update_dsp_change_configuration(self, config):
        # Move from FSP to FCT
        for fsp in self.fsps_states.keys():
            for dsp in self.fsps_states[fsp]:
                self.__update_change_per_dsp(config, dsp, fsp)

    def __update_change_per_dsp(self, config, dsp_state, fsp_state):
        # Move from sepcific FSP to specific DSP (of its pool)
        dsp_number = CusController.__get_dsp_number_from_state(dsp_state)
        config[CusController.connection_hops][fsp_state][dsp_state] = \
            self.__generate_change_to_dsp_sm_configuration(dsp_number=dsp_number, fsp_state=fsp_state)
        # Move from DSP to its FSP
        config[CusController.connection_hops][dsp_state] = \
            self.__generate_change_from_dsp_sm_configuration(dsp_number=dsp_number, fsp=fsp_state)

    def __update_change_per_fsp(self, config):
        for fsp in self.fsps_states.keys():
            config[CusController.connection_hops][fsp] = {
                CusController.fct: CusController.__generate_change_to_fct_from_fsp_sm_configuration()
            }
            config[CusController.connection_hops][CusController.fct][fsp] = \
                CusController.__generate_change_to_fsp_from_fct_sm_configuration(fsp_state=fsp)

    @staticmethod
    def __get_dsp_number_from_state(dsp_state):
        dsp_number = re.findall(r"dsp(\d)", dsp_state)[0]
        return dsp_number

    def __generate_dsp_prompt(self, dsp_number, fsp_state):
        # Currently not supporting core 2 and 3 until prompt change.
        if re.match("fsp-[1-3][a-d]", fsp_state):
            return f"Core l?[0-9a-fA-F]{self.node_ids[fsp_state]}.{dsp_number}>"
        elif re.match("fsp-[5-7][a-d]", fsp_state):
            return f"Core r?[0-9a-fA-F]{self.node_ids[fsp_state]}.{dsp_number}>"

    @staticmethod
    def __generate_fct_prompt():
        return r"fct-\d*\w*:~\s*>"

    @staticmethod
    def __generate_fsp_prompt(fsp_state):
        return rf"{fsp_state}:~\s*>"

    def __get_expected_prompt_for_proxy_pc(self):
        return self._configurations[CusController.connection_hops][CusController.fct][CusController.proxy_pc][
            "command_params"]["expected_prompt"]

    def get_cus_airscale_side(self):
        """
        Get side of airscale for this device.

        @return: left or right side of CUS controller
        """
        return self._cus_airscale_side
